use crate::*;
use super::{policy,performance,update};
use sha2::{Digest,Sha256};
use std::sync::{Mutex,OnceLock};
fn lock()->&'static Mutex<()>{static L:OnceLock<Mutex<()>>=OnceLock::new();L.get_or_init(Mutex::default)}
fn load(core:&Core)->Value{read_json(&core.data_root.join("agent-insights.json")).unwrap_or_else(|_|json!({"version":1,"items":[],"crashes":{},"checked":{}}))}
fn store(core:&Core,value:&Value)->Result<()>{let target=core.data_root.join("agent-insights.json");let temp=target.with_extension(format!("{}.tmp",uuid::Uuid::new_v4()));write_json(&temp,value)?;std::fs::rename(temp,target).map_err(err)}
fn visible(item:&Value)->bool{item["ignoredForever"]!=true&&item["ignoredUntil"].as_u64().unwrap_or(0)<=policy::now()}
pub fn list(core:&Core,mark_read:bool)->Result<Value>{let _guard=lock().lock().map_err(err)?;let mut v=load(core);if mark_read{for item in v["items"].as_array_mut().into_iter().flatten(){if visible(item){item["seen"]=json!(true);}}store(core,&v)?;}Ok(json!(v["items"].as_array().into_iter().flatten().filter(|v|visible(v)).cloned().collect::<Vec<_>>()))}
pub fn dismiss(core:&Core,key:&str,forever:bool)->Result<Value>{let _guard=lock().lock().map_err(err)?;let mut v=load(core);let item=v["items"].as_array_mut().into_iter().flatten().find(|i|i["key"]==key).ok_or("提醒已不存在")?;item["ignoredForever"]=json!(forever);item["ignoredUntil"]=json!(policy::now()+7*24*3600);item["seen"]=json!(true);store(core,&v)?;Ok(json!({"dismissed":true}))}
pub fn signature(log:&str)->String{let excerpt=ai_diagnose::agent_text(log).lines().filter(|s|s.contains("ERROR")||s.contains("Exception")||s.contains("Caused by")||s.contains("OutOfMemory")).take(6).collect::<Vec<_>>().join("\n");let normalized=regex::Regex::new(r"\b[0-9a-fA-F]{8,}\b|\d{2}:\d{2}:\d{2}").unwrap().replace_all(&excerpt,"#");format!("{:x}",Sha256::digest(normalized.as_bytes()))}
pub fn record_exit(core:&Core,id:&str,log:&str,abnormal:bool)->Result<()>{let _guard=lock().lock().map_err(err)?;safe_name(id)?;let prefix=format!("{}:{id}",super::root_hash(core)?);let mut v=load(core);if !abnormal{if let Some(crashes)=v["crashes"].as_object_mut(){crashes.remove(&prefix);}if let Some(items)=v["items"].as_array_mut(){items.retain(|i|i["key"]!=format!("crash:{prefix}"));}}else{let hash=signature(log);let old=&v["crashes"][&prefix];let count=if old["signature"]==hash{old["count"].as_u64().unwrap_or(0)+1}else{1};v["crashes"][&prefix]=json!({"signature":hash,"count":count,"at":policy::now(),"instanceId":id});}store(core,&v)}
fn put(value:&mut Value,mut item:Value){let key=item["key"].clone();let now=policy::now();let items=value["items"].as_array_mut().unwrap();if let Some(old)=items.iter_mut().find(|i|i["key"]==key){item["ignoredUntil"]=old["ignoredUntil"].clone();item["ignoredForever"]=old["ignoredForever"].clone();let recent=old["notifiedAt"].as_u64().unwrap_or(0)+86400>now;item["seen"]=if recent{old["seen"].clone()}else{json!(false)};item["notifiedAt"]=if recent{old["notifiedAt"].clone()}else{json!(now)};*old=item;}else{item["notifiedAt"]=json!(now);item["seen"]=json!(false);items.push(item);}if items.len()>200{items.remove(0);}}
pub async fn check(core:&Core,force:bool)->Result<Value>{let root_key=super::root_hash(core)?;let initial={let _g=lock().lock().map_err(err)?;load(core)};if !force&&initial["checked"][&root_key].as_u64().unwrap_or(0)+6*3600>policy::now(){return list(core,false);}let mut findings=Vec::new();if performance::disk_free(&core.root).is_some_and(|n|n<5*1024*1024*1024){findings.push(json!({"key":format!("disk:{root_key}"),"kind":"disk","title":"游戏目录所在磁盘空间偏低","message":"可用空间不足 5 GB，请自行清理不需要的内容或更换游戏目录；工坊不会自动删除文件。"}));}
 let instances=core.instances()?;for cfg in instances.as_array().into_iter().flatten().take(100){core.stopped()?;let id=string(cfg,"id")?;let key=format!("{root_key}:{id}");let crash=&initial["crashes"][&key];if crash["count"].as_u64().unwrap_or(0)>=2{findings.push(json!({"key":format!("crash:{key}"),"kind":"crash","instanceId":id,"title":format!("{} 重复出现相同崩溃",ai_diagnose::agent_text(cfg["name"].as_str().unwrap_or("实例"))),"message":"同一崩溃签名已出现两次以上，可添加日志分析或使用安全模式排查。"}));}
  let root=core.instance(id)?;if let Ok(meta)=read_json(&root.join("version.json")){let required=meta["javaVersion"]["majorVersion"].as_u64();if let Some(path)=cfg["settings"]["java"].as_str().filter(|s|!s.is_empty()){if let Ok(rows)=engine::java_list_at(core){if let Some(java)=rows.as_array().into_iter().flatten().find(|v|v["path"]==path){if required.is_some()&&java["major"].as_u64()!=required{findings.push(json!({"key":format!("java:{key}"),"kind":"java","instanceId":id,"title":"手动 Java 与游戏要求不一致","message":format!("该实例需要 Java {}，建议切换为自动匹配。",required.unwrap())}));}}}}}
  if cfg["packSource"].is_object(){if let Ok(info)=update::check(core,id).await{if info["preview"]["available"]==true{findings.push(json!({"key":format!("pack:{key}"),"kind":"pack_update","instanceId":id,"title":"整合包有兼容版本可更新","message":"请在工坊查看更新说明与差异，确认后再更新。"}));}}}
  let mut count=0;for item in update::identities(core,id).unwrap_or_default().into_iter().take(80){core.stopped()?;let pid=string(&item,"projectId")?;if item["source"]=="modrinth"{let current=core.get(&format!("https://api.modrinth.com/v2/version/{}",string(&item,"versionId")?)).await;let latest=engine::project_version(core,pid,string(cfg,"version")?,string(cfg,"loader")?,"mods").await;if let(Ok(a),Ok(b))=(current,latest){if a["id"]!=b["id"]&&b["date_published"].as_str().zip(a["date_published"].as_str()).is_some_and(|(b,a)|b>a){count+=1;}}}else{let token=curseforge::configured_key(core,"");if let(Ok(pid),Ok(vid))=(pid.parse(),string(&item,"versionId")?.parse()){let a=curseforge::file_by_id(core,pid,vid,token.as_deref()).await;let b=curseforge::best_file(core,pid,Some(string(cfg,"version")?),Some(string(cfg,"loader")?),token.as_deref()).await;if let(Ok(a),Ok(b))=(a,b){if a["id"]!=b["id"]&&b["fileDate"].as_str().zip(a["fileDate"].as_str()).is_some_and(|(b,a)|b>a){count+=1;}}}}}
  if count>0{findings.push(json!({"key":format!("mods:{key}"),"kind":"mod_update","instanceId":id,"title":format!("{count} 个模组存在更新"),"message":"仅作提醒，不会自动更新；请在模组管理中核对兼容性与变更说明。"}));}
 }
 let _guard=lock().lock().map_err(err)?;let mut value=load(core);let keys=findings.iter().filter_map(|i|i["key"].as_str().map(str::to_owned)).collect::<std::collections::HashSet<_>>();if let Some(items)=value["items"].as_array_mut(){items.retain(|i|{let key=i["key"].as_str().unwrap_or("");!key.contains(&root_key)||keys.contains(key)||i["ignoredForever"]==true||i["ignoredUntil"].as_u64().unwrap_or(0)>policy::now()});}for item in findings{put(&mut value,item);}value["checked"][root_key]=json!(policy::now());store(core,&value)?;Ok(json!(value["items"].as_array().into_iter().flatten().filter(|i|visible(i)).cloned().collect::<Vec<_>>()))
}
#[cfg(test)]mod tests{use super::*;#[test]fn dedup_and_ignores(){let t=tempfile::tempdir().unwrap();let c=Core::new(t.path().into(),Arc::new(|_|{})).unwrap();let mut value=load(&c);put(&mut value,json!({"key":"x","title":"提醒"}));store(&c,&value).unwrap();list(&c,true).unwrap();let mut value=load(&c);put(&mut value,json!({"key":"x","title":"提醒"}));assert_eq!(value["items"].as_array().unwrap().len(),1);assert_eq!(value["items"][0]["seen"],true);store(&c,&value).unwrap();dismiss(&c,"x",false).unwrap();assert!(list(&c,false).unwrap().as_array().unwrap().is_empty());let mut value=load(&c);put(&mut value,json!({"key":"x","title":"提醒"}));store(&c,&value).unwrap();assert!(list(&c,false).unwrap().as_array().unwrap().is_empty());}#[test]fn crash_signature_is_local_and_repeatable(){let a="[12:01:02] ERROR java.lang.OutOfMemoryError";let b="[13:02:03] ERROR java.lang.OutOfMemoryError";assert_eq!(signature(a),signature(b));let t=tempfile::tempdir().unwrap();let c=Core::new(t.path().into(),Arc::new(|_|{})).unwrap();record_exit(&c,"x",a,true).unwrap();record_exit(&c,"x",b,true).unwrap();let v=load(&c);let key=format!("{}:x",super::super::root_hash(&c).unwrap());assert_eq!(v["crashes"][key]["count"],2);}}
